#include <stdio.h>
#define SENSOR_SQUARE(x) ((x) * (x))
int main(void) {
    int x;
    if (scanf("%d", &x) != 1) return 1;
    printf("%d\n", SENSOR_SQUARE(x));
    return 0;
}
